1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.time.LocalDate;
13	import java.time.Period;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public abstract class OwnerMapper {
22	
23	    @Mapping(target = "displayName",
24	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials",
26	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
27	                    + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
30	    @Mapping(target = "locality", expression = "java(locality(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
32	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
33	    @Mapping(target = "identityKey",
34	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.forOwner(owner))")
35	    @Mapping(target = "telephoneDisplay",
36	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneNormalizer.toDisplay(owner.getTelephone()))")
37	    public abstract OwnerDto toOwnerDto(Owner owner);
38	
39	    public abstract Owner toOwner(OwnerDto ownerDto);
40	
41	    @Mapping(target = "id", ignore = true)
42	    @Mapping(target = "pets", ignore = true)
43	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
44	
45	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
46	
47	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
48	
49	    /**
50	     * Derives the owner's numeric membership level, assigned on creation. Starts at 1;
51	     * add 1 when an email address is on file; add 1 when the owner is the first with
52	     * their name ({@code namesakeCount} is 0); capped at 3 (level 4 is reserved for
53	     * tenure).
54	     */
55	    protected Integer membershipLevel(Owner owner) {
56	        int level = 1;
57	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
58	            level++;
59	        }
60	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
61	            level++;
62	        }
63	        return Math.min(level, 3);
64	    }
65	
66	    /**
67	     * Computes a single Luhn check digit (0-9) over the digits contained in the owner's
68	     * {@code customerCode}. Non-digit characters (separators) are ignored. Returns
69	     * {@code null} when no customer code has been assigned.
70	     */
71	    protected Integer checkDigit(Owner owner) {
72	        String code = owner.getCustomerCode();
73	        if (code == null) {
74	            return null;
75	        }
76	        int sum = 0;
77	        boolean dbl = true;
78	        for (int i = code.length() - 1; i >= 0; i--) {
79	            char c = code.charAt(i);
80	            if (c < '0' || c > '9') {
81	                continue;
82	            }
83	            int d = c - '0';
84	            if (dbl) {
85	                d *= 2;
86	                if (d > 9) {
87	                    d -= 9;
88	                }
89	            }
90	            sum += d;
91	            dbl = !dbl;
92	        }
93	        return (10 - (sum % 10)) % 10;
94	    }
95	
96	    /**
97	     * Derives the owner's {@code locality} from the REGION component of the
98	     * {@code <REGION>-<HASH8>} customer code — the region-and-hash identity is now the single
99	     * source of the owner's region. Falls back to the postcode/city lookup for an owner that has
100	     * no customer code yet (e.g. seed data created outside the create pipeline).
101	     */
102	    protected String locality(Owner owner) {
103	        String code = owner.getCustomerCode();
104	        if (code != null) {
105	            int dash = code.indexOf('-');
106	            return dash >= 0 ? code.substring(0, dash) : code;
107	        }
108	        return LocalityLookup.regionFor(owner.getCity(), owner.getPostcode());
109	    }
110	
111	    /**
112	     * Derives the owner's preferred contact channel: 'EMAIL' when an email address is
113	     * on file, otherwise 'PHONE'.
114	     */
115	    protected String contactPreference(Owner owner) {
116	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
117	    }
118	
119	    /**
120	     * Derives the owner's age band from their birthDate as of their registrationDate:
121	     * 'MINOR' when under 18, 'ADULT' when 18-64, 'SENIOR' when 65 or over. Returns
122	     * {@code null} when no birthDate is on file (the field is then absent from the
123	     * response). The reference date is the registrationDate, falling back to the current
124	     * date only for legacy owners created without one.
125	     */
126	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
127	        LocalDate birthDate = owner.getBirthDate();
128	        if (birthDate == null) {
129	            return null;
130	        }
131	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
132	        int age = Period.between(birthDate, asOf).getYears();
133	        if (age < 18) {
134	            return OwnerDto.AgeBandEnum.MINOR;
135	        }
136	        if (age < 65) {
137	            return OwnerDto.AgeBandEnum.ADULT;
138	        }
139	        return OwnerDto.AgeBandEnum.SENIOR;
140	    }
